def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    def parse_amount(token):
        if not token or any(c < "0" or c > "9" for c in token):
            return None
        value = 0
        for i in range(0, len(token), 9):
            chunk = token[i:i + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        tokens = operation.split(" ")
        verb = tokens[0]

        if verb == "undo" and len(tokens) == 1:
            if not history:
                rejected.append(index)
                continue

            action = history.pop()
            kind = action[0]

            if kind == "open":
                del balances[action[1]]
                frozen.discard(action[1])
            elif kind == "deposit":
                balances[action[1]] -= action[2]
            elif kind == "withdraw":
                balances[action[1]] += action[2]
            elif kind == "transfer":
                balances[action[1]] += action[3]
                balances[action[2]] -= action[3]
            elif kind == "freeze":
                frozen.remove(action[1])
            else:
                frozen.add(action[1])
            continue

        if verb in ("open", "deposit", "withdraw") and len(tokens) == 3:
            account = tokens[1]
            amount = parse_amount(tokens[2])

            if amount is None:
                rejected.append(index)
                continue

            if verb == "open":
                if account in balances:
                    rejected.append(index)
                    continue
                balances[account] = amount
            elif verb == "deposit":
                if account not in balances or amount == 0:
                    rejected.append(index)
                    continue
                balances[account] += amount
            else:
                if (
                    account not in balances
                    or account in frozen
                    or amount == 0
                    or balances[account] < amount
                ):
                    rejected.append(index)
                    continue
                balances[account] -= amount

            history.append((verb, account, amount))
            continue

        if verb == "transfer" and len(tokens) == 4:
            source, destination = tokens[1], tokens[2]
            amount = parse_amount(tokens[3])

            if (
                amount is None
                or amount == 0
                or source == destination
                or source not in balances
                or destination not in balances
                or source in frozen
                or balances[source] < amount
            ):
                rejected.append(index)
                continue

            balances[source] -= amount
            balances[destination] += amount
            history.append((verb, source, destination, amount))
            continue

        if verb in ("freeze", "unfreeze") and len(tokens) == 2:
            account = tokens[1]

            if account not in balances:
                rejected.append(index)
                continue

            if verb == "freeze":
                if account in frozen:
                    rejected.append(index)
                    continue
                frozen.add(account)
            else:
                if account not in frozen:
                    rejected.append(index)
                    continue
                frozen.remove(account)

            history.append((verb, account))
            continue

        rejected.append(index)

    return balances, rejected
